-- SPE-A07: strict private staging for sanitized WebP images.
-- Object keys are generated by the server and never returned to the client.
CREATE TABLE feed.paid_image_uploads (
 tenant_id text NOT NULL,id uuid NOT NULL DEFAULT gen_random_uuid(),
 owner_id text NOT NULL,idempotency_key text NOT NULL,
 request_sha256 text NOT NULL CHECK(request_sha256~'^[0-9a-f]{64}$'),
 object_key text NOT NULL CHECK(length(object_key) BETWEEN 20 AND 400),
 bytes integer NOT NULL CHECK(bytes BETWEEN 1 AND 1048576),
 rights_confirmed boolean NOT NULL CHECK(rights_confirmed),
 alt_text text NOT NULL CHECK(length(btrim(alt_text)) BETWEEN 5 AND 280),
 state text NOT NULL DEFAULT 'staging' CHECK(state IN ('staging','ready','rejected')),
 post_id uuid,
 created_at timestamptz NOT NULL DEFAULT statement_timestamp(),
 uploaded_at timestamptz,
 PRIMARY KEY(tenant_id,id),UNIQUE(tenant_id,owner_id,idempotency_key),
 UNIQUE(tenant_id,object_key),
 FOREIGN KEY(tenant_id,post_id) REFERENCES feed.posts(tenant_id,id),
 CHECK((state='staging' AND uploaded_at IS NULL) OR (state IN ('ready','rejected') AND uploaded_at IS NOT NULL))
);
CREATE INDEX paid_image_upload_owner ON feed.paid_image_uploads(tenant_id,owner_id,created_at DESC);
CREATE INDEX paid_image_upload_staging ON feed.paid_image_uploads(created_at)
 WHERE state='staging';
ALTER TABLE feed.promotion_drafts ADD COLUMN media_ids text[] NOT NULL DEFAULT '{}' CHECK(cardinality(media_ids)<=10);
ALTER TABLE feed.paid_post_media_objects ADD COLUMN reviewed_by text;
ALTER TABLE feed.paid_post_media_objects ADD COLUMN reviewed_at timestamptz;
ALTER TABLE feed.paid_post_media_objects ADD COLUMN review_reason text;
ALTER TABLE feed.paid_post_media_objects ADD CONSTRAINT paid_media_review_provenance CHECK (
 (review_state='pending' AND reviewed_by IS NULL AND reviewed_at IS NULL)
 OR (review_state IN ('approved','rejected') AND reviewed_by IS NOT NULL AND reviewed_at IS NOT NULL));
CREATE UNIQUE INDEX paid_single_image_post ON feed.paid_image_uploads(tenant_id,id,post_id);
-- Image proposals reuse the existing immutable-edit source checks.
ALTER TABLE feed.promotion_edit_proposals ADD COLUMN proposed_media_ids text[];
ALTER TABLE feed.promotion_edit_proposals ADD CONSTRAINT paid_edit_media_count
 CHECK(proposed_media_ids IS NULL OR cardinality(proposed_media_ids) BETWEEN 1 AND 10);
CREATE OR REPLACE FUNCTION feed.refuse_promotion_edit_proposal_changes()
RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
 IF (OLD.tenant_id,OLD.id,OLD.post_id,OLD.owner_id,OLD.original_revision,
     OLD.idempotency_key,OLD.request_sha256,OLD.proposed_body,OLD.proposed_destination_url,
     OLD.proposed_media_ids) IS DISTINCT FROM
    (NEW.tenant_id,NEW.id,NEW.post_id,NEW.owner_id,NEW.original_revision,
     NEW.idempotency_key,NEW.request_sha256,NEW.proposed_body,NEW.proposed_destination_url,
     NEW.proposed_media_ids)
 THEN RAISE EXCEPTION 'Paid edit proposal source is immutable'; END IF;
 RETURN NEW;
END $$;
REVOKE ALL ON ALL TABLES IN SCHEMA feed FROM PUBLIC;
